"""
Index page generator.

A page with an `index:` list in its front matter gets the section under each listed heading filled in with
pages (or table rows) picked out of the metadata aggregator's database, extracted_metadata.json:

    index:
      - heading: "Stars Published During the God-War Era"   # the heading whose section is written
        type: list                                          # `list` (default) or `table`
        include:                                            # every condition must hold
          tags: {all: [topic/geography/astrography, "subject/star*"]}
          star[].publications[].date: {to: [-1]}
        exclude:                                            # pages matching any of these are left out
          type: archive
        order:                                              # sort by the first entry, then the next...
          - by: star[].publications[].date
            group: {by: star[].publications[].date.decade}  # a subheading for each decade
          - by: title
        columns:                                            # tables only: heading -> path
          Star: star[].name

Every path reads a page's metadata exactly as it appears in extracted_metadata.json:
    a.b      key b inside a
    a[0]     the first item of list a
    a[]      every item of list a
If a path gives several values (because of [] or because the field is a list), a condition holds when any
of them matches, and sorting and grouping use the first one. Full reference: Meta/Metadata.md.

The program is organised in the order it works:
    1. Paths      reading values out of a page
    2. Rows       what one entry is (a page, or for tables maybe one item of a list on a page)
    3. Matching   include / exclude
    4. Ordering   sorting and grouping
    5. Output     lists and tables
    6. Pages      finding each heading on each index page and writing its section
"""
import re
import sys
import json
import pathlib
from typing import Any, Dict, List, Optional

# Shared settings and helpers: Meta/Programs/mysenvar_common.py
sys.dont_write_bytecode = True  # keeps __pycache__ folders out of the vault
for _p in pathlib.Path(__file__).resolve().parents:
    if (_p / "Meta/Programs/mysenvar_common.py").is_file():
        sys.path.insert(0, str(_p / "Meta/Programs")); break
import mysenvar_common as mc

# ===================== CONFIG =====================
DRY_RUN = False

INDEX_KEYS = {"heading", "type", "include", "exclude", "order", "columns", "item"}
OLD_KEYS = {"header_name", "included_data", "excluded_data", "sort"}


# =============================================================================
#  1. Paths
# =============================================================================
STEP_RE = re.compile(r"^(?P<key>[^\[\]]+)(?:\[(?P<idx>\d*)\])?$")


def get_values(obj: Any, path: str) -> List[Any]:
    """Every value at `path` inside obj. `a[]` steps into every item of list a, `a[0]` into the first.
    A list at the end of the path gives its items, so `tags` gives each tag."""
    nodes = [obj]
    for step in [s for s in str(path).split(".") if s]:
        m = STEP_RE.match(step)
        if not m:
            return []
        key, idx = m.group("key"), m.group("idx")
        nxt = []
        for node in nodes:
            if not isinstance(node, dict) or node.get(key) is None:
                continue
            val = node[key]
            if idx is None:
                nxt.append(val)
            elif not isinstance(val, list):
                continue
            elif idx == "":
                nxt.extend(val)
            elif int(idx) < len(val):
                nxt.append(val[int(idx)])
        nodes = nxt
    out = []
    for n in nodes:
        out.extend(n if isinstance(n, list) else [n])
    return [v for v in out if v is not None and v != ""]


def is_date(v: Any) -> bool:
    """A date object made by the aggregator (see mc.normalise_date)."""
    return isinstance(v, dict) and "sort" in v and "original" in v


def as_text(v: Any) -> str:
    """How a value is written in a heading or a table cell: dates in words, yes/no for true/false."""
    if is_date(v):
        return v.get("formal", "")
    if isinstance(v, bool):
        return "Yes" if v else "No"
    if isinstance(v, (dict, list)):
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v)


# =============================================================================
#  2. Rows
# =============================================================================
# A list has one entry per page. A table has one row per page too, unless a column reads a list with []
# (`star[].name`): then each item of that list is a row of its own, and every path that starts with that
# list (`star[]...`, in columns, conditions and order alike) reads from the row's own item.

class Row:
    def __init__(self, page: Dict[str, Any], base: Optional[str] = None, item: Any = None):
        self.page, self.meta, self.base, self.item = page, page["metadata"], base, item

    def values(self, path: str) -> List[Any]:
        if self.base and (path == self.base or path.startswith(self.base + ".")):
            rest = path[len(self.base) + 1:]
            return [self.item] if not rest else get_values(self.item, rest)
        return get_values(self.meta, path)

    def first(self, path: str) -> Any:
        vals = self.values(path)
        return vals[0] if vals else None


def row_list_of(columns: Dict[str, str]) -> Optional[str]:
    """The list a table's rows are items of ("star[]"), from the first column that reads one."""
    for path in columns.values():
        steps = str(path).split(".")
        for i, step in enumerate(steps):
            if step.endswith("[]"):
                return ".".join(steps[: i + 1])
    return None


def rows_of(page: Dict[str, Any], base: Optional[str]) -> List[Row]:
    if not base:
        return [Row(page)]
    return [Row(page, base, it) for it in get_values(page["metadata"], base) if isinstance(it, dict)]


# =============================================================================
#  3. Matching
# =============================================================================
# A condition is one of:
#   value              equal to it (text ending in * matches anything starting with the rest)
#   [a, b]             any of these
#   {all: [a, b]}      every one of these (for list fields such as tags)
#   {exists: true}     has a value at all ({exists: false}: has none)
#   {from: x, to: y}   between x and y, both included; {after: x} / {before: y} leave them out.
#                      Numbers compare as numbers; dates compare as dates, with the bounds written as dates
#                      ([year] or [year, day]): {to: [-1]} is "1 BT or earlier", {from: [-178, 330]} is
#                      "the 60th of Winter, 178 BT or later".

def same(v: Any, want: Any) -> bool:
    a, b = as_text(v), as_text(want)
    return a.startswith(b[:-1]) if b.endswith("*") else a == b


def date_bound(bound: Any, end: bool) -> Optional[int]:
    """A date bound as a sort number. A year on its own covers the whole year: from [y] starts on its first
    day, to [y] runs to its last."""
    d = mc.normalise_date(bound if isinstance(bound, (list, dict)) else [bound])
    if d is None:
        return None
    return d["sort"] + (mc.DAYS_PER_YEAR if end and d["day"] is None else 0)


def in_range(v: Any, cond: Dict[str, Any]) -> bool:
    if is_date(v):
        x = v["sort"]
        lo = lambda b: date_bound(b, False)
        hi = lambda b: date_bound(b, True)
    elif isinstance(v, (int, float)) and not isinstance(v, bool):
        x = v
        lo = hi = lambda b: b if isinstance(b, (int, float)) and not isinstance(b, bool) else None
    else:
        return False
    checks = {"from": lambda b: x >= lo(b), "after": lambda b: x > hi(b),
              "to": lambda b: x <= hi(b), "before": lambda b: x < lo(b)}
    for op, bound in cond.items():
        if op in checks:
            if (lo(bound) if op in ("from", "before") else hi(bound)) is None or not checks[op](bound):
                return False
    return True


def holds(vals: List[Any], cond: Any) -> bool:
    if isinstance(cond, dict):
        if "exists" in cond:
            return bool(vals) == bool(cond["exists"])
        if "all" in cond:
            wants = cond["all"] if isinstance(cond["all"], list) else [cond["all"]]
            return all(any(same(v, w) for v in vals) for w in wants)
        return any(in_range(v, cond) for v in vals)
    wants = cond if isinstance(cond, list) else [cond]
    return any(same(v, w) for v in vals for w in wants)


def conditions(spec: Any) -> List[tuple]:
    """include/exclude as (path, condition) pairs. Written as one mapping, or as a list of mappings when the
    same path is needed twice."""
    parts = spec if isinstance(spec, list) else [spec] if spec else []
    out = []
    for part in parts:
        if isinstance(part, dict):
            out.extend(part.items())
        elif isinstance(part, str):
            out.append((part, {"exists": True}))
    return out


def wanted(row: Row, include: List[tuple], exclude: List[tuple]) -> bool:
    if not all(holds(row.values(p), c) for p, c in include):
        return False
    return not any(holds(row.values(p), c) for p, c in exclude)


# =============================================================================
#  4. Ordering
# =============================================================================
# order: a list of {by: path}, each sorting what the one before it left tied. Options:
#   reverse: true     largest / latest / Z first
#   natural: true     numbers inside text sort by value ("Item 2" before "Item 10")
#   group:            a subheading for each group, one heading level below the last
#       value             one per distinct value of `by`
#       first_letter      one per first letter of `by`
#       {by: path, first_letter: true, every: 10, strip: 7, heading: "{value} Gods"}
#                         group by another path; `every` groups numbers in steps (0-9, 10-19...);
#                         `strip` drops characters from the front before the letter or value is taken;
#                         `heading` is the subheading's text, {value} being the group.

def sort_key(row: Row, step: Dict[str, Any]):
    v = row.first(step.get("by", "title"))
    if v is None:
        return (2, 0, "")                            # missing values go last
    if is_date(v):
        return (0, v["sort"], "")
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return (0, v, "")
    text = as_text(v)
    if step.get("natural"):
        return (1, 0, [int(c) if c.isdigit() else c.lower() for c in re.split(r"(\d+)", text)])
    return (1, 0, text)


def group_label(row: Row, step: Dict[str, Any]) -> str:
    g = step.get("group")
    opts = g if isinstance(g, dict) else {"first_letter": g == "first_letter"}
    v = row.first(opts.get("by") or step.get("by", "title"))
    if v is None:
        return "Other"
    every = opts.get("every")
    if every and isinstance(v, (int, float)) and not isinstance(v, bool):
        text = as_text(int(v // every * every))
    else:
        text = as_text(v)
    strip = int(opts.get("strip") or 0)
    text = text[strip:].lstrip() if strip else text
    if opts.get("first_letter"):
        text = text[:1].upper()
    return text or "Other"


def heading_text(label: str, step: Dict[str, Any]) -> str:
    g = step.get("group")
    fmt = g.get("heading", "{value}") if isinstance(g, dict) else "{value}"
    return fmt.replace("{value}", label)


def order_rows(rows: List[Row], order: List[Dict[str, Any]]) -> List[Row]:
    out = list(rows)
    for step in reversed(order):                     # stable sorts: the first step ends up deciding first
        out.sort(key=lambda r: sort_key(r, step), reverse=bool(step.get("reverse")))
    return out


# =============================================================================
#  5. Output
# =============================================================================
def cell(vals: List[Any]) -> str:
    """One table cell: values joined with commas, on one line, with `|` escaped so a link's
    [[page|name]] doesn't split the cell."""
    text = ", ".join(as_text(v) for v in vals)
    text = re.sub(r"\s*\n\s*", " ", text)
    return re.sub(r"(?<!\\)\|", r"\\|", text)


def render_list(rows: List[Row], config: Dict[str, Any]) -> List[str]:
    item = config.get("item", "link")
    return [f"- {as_text(r.first(item)) if r.first(item) is not None else ''}" for r in rows]


def render_table(rows: List[Row], config: Dict[str, Any]) -> List[str]:
    cols = config["columns"]
    lines = ["| " + " | ".join(cell([t]) for t in cols) + " |", "| " + " | ".join("---" for _ in cols) + " |"]
    lines += ["| " + " | ".join(cell(r.values(p)) for p in cols.values()) + " |" for r in rows]
    return [""] + lines + [""]                      # a table needs blank lines around it


def render(rows: List[Row], config: Dict[str, Any], level: int) -> List[str]:
    if not rows:
        return [""]                                  # keep the blank line before whatever follows
    order = config["order"]
    leaf = render_table if config["type"] == "table" else render_list

    def section(rs: List[Row], i: int, lvl: int) -> List[str]:
        while i < len(order) and not order[i].get("group"):
            i += 1
        if i >= len(order):
            return leaf(rs, config)
        groups: Dict[str, List[Row]] = {}
        for r in rs:
            groups.setdefault(group_label(r, order[i]), []).append(r)
        out = []
        for label, members in groups.items():        # in the order the rows were sorted
            out.append(f"{'#' * min(lvl + 1, 6)} {heading_text(label, order[i])}")
            out += section(members, i + 1, lvl + 1)
        return out

    out = section(order_rows(rows, order), 0, level)
    while out and out[-1] == "":
        out.pop()
    return out + [""]


# =============================================================================
#  6. Pages
# =============================================================================
def read_config(raw: Dict[str, Any], where: str) -> Optional[Dict[str, Any]]:
    """An index entry, checked and with its defaults filled in; None (and a message) if it can't be used."""
    if not isinstance(raw, dict):
        print(f"[SKIP] {where}: an index entry should be a set of keys.")
        return None
    if OLD_KEYS & set(raw) and "heading" not in raw:
        print(f"[SKIP] {where}: uses the old index format ({', '.join(sorted(OLD_KEYS & set(raw)))}). "
              "See the Index section of Meta/Metadata.md for the current one.")
        return None
    unknown = set(raw) - INDEX_KEYS
    if unknown:
        print(f"[NOTE] {where}: ignoring unknown key(s) {', '.join(sorted(unknown))}.")
    cfg = {"heading": str(raw.get("heading") or "").strip(), "type": str(raw.get("type") or "list").strip().lower(),
           "include": conditions(raw.get("include")), "exclude": conditions(raw.get("exclude")),
           "order": [s if isinstance(s, dict) else {"by": s} for s in (raw.get("order") or [])],
           "columns": raw.get("columns") or {}, "item": raw.get("item") or "link"}
    if not cfg["heading"]:
        print(f"[SKIP] {where}: no `heading`.")
        return None
    if cfg["type"] not in ("list", "table"):
        print(f"[SKIP] {where}: `type` is \"{cfg['type']}\"; it should be list or table.")
        return None
    if cfg["type"] == "table" and (not isinstance(cfg["columns"], dict) or not cfg["columns"]):
        print(f"[SKIP] {where}: a table needs `columns` (Column title: path).")
        return None
    return cfg


def section_span(lines: List[str], heading: str):
    """(first line, end line, heading level) of the section under `heading`. The section ends at the next
    heading of the same or a higher level, at a callout, or at a %% comment block, so definitions kept at the
    bottom of a page are never written over, even under its last heading."""
    for i, ln in enumerate(lines):
        m = re.match(r"^(#{1,6})\s+(.*?)\s*$", ln)
        if m and m.group(2).strip() == heading:
            lvl = len(m.group(1))
            for j in range(i + 1, len(lines)):
                h = re.match(r"^(#{1,6})\s", lines[j])
                if lines[j].startswith("> [!") or lines[j].lstrip().startswith("%%") or (h and len(h.group(1)) <= lvl):
                    return i + 1, j, lvl
            return i + 1, len(lines), lvl
    return None


def unknown_paths(cfg: Dict[str, Any], pages: List[Dict[str, Any]], base: Optional[str]) -> List[str]:
    """Paths in an index entry that no page has a value at, which is almost always a typo."""
    paths = [p for p, _ in cfg["include"] + cfg["exclude"]] + [s.get("by", "title") for s in cfg["order"]]
    paths += [s["group"]["by"] for s in cfg["order"] if isinstance(s.get("group"), dict) and s["group"].get("by")]
    paths += list(cfg["columns"].values()) + [cfg["item"]]
    missing = []
    for path in dict.fromkeys(paths):
        if not any(r.values(path) for p in pages for r in rows_of(p, base)):
            missing.append(path)
    return missing


def main():
    root = mc.VAULT
    pages = mc.load_metadata().get("pages", [])
    index_pages = [p for p in pages if isinstance(p["metadata"].get("index"), list)]

    wrote = 0
    for page in index_pages:
        rel = (page.get("parent") or page.get("src_rel")).split("::")[0]
        path = root / rel
        if not path.exists():
            continue
        try:
            raw = path.read_bytes().decode("utf-8")
        except Exception:
            continue
        newline = "\r\n" if "\r\n" in raw else "\n"     # write the page back with its own line endings
        lines = raw.replace("\r\n", "\n").split("\n")
        if lines and lines[-1] == "":
            lines.pop()

        changed = False
        for n, raw in enumerate(page["metadata"]["index"]):
            where = f"{rel} index[{n}]"
            cfg = read_config(raw, where)
            if not cfg:
                continue
            span = section_span(lines, cfg["heading"])
            if not span:
                print(f"[SKIP] {where}: the page has no heading \"{cfg['heading']}\".")
                continue
            start, end, level = span

            base = row_list_of(cfg["columns"]) if cfg["type"] == "table" else None
            for missing in unknown_paths(cfg, pages, base):
                print(f"[WARN] {where}: no page has anything at `{missing}`. Check it against extracted_metadata.json.")
            rows = [r for p in pages for r in rows_of(p, base) if wanted(r, cfg["include"], cfg["exclude"])]

            new = render(rows, cfg, level)
            if lines[start:end] != new:
                lines[start:end] = new
                changed = True

        if changed:
            if DRY_RUN:
                print(f"[DRY-RUN] Would update {path.name}")
            else:
                path.write_bytes((newline.join(lines).rstrip() + newline).encode("utf-8"))
                print(f"[UPDATED] {path.name}")
                wrote += 1

    print(f"Done. Processed {len(pages)} entries, updated {wrote} indexes.")


if __name__ == "__main__":
    main()
